        keep.add(i)
if c.get("filter")!="context": sys.exit(1)
if c.get("sections")!=len(ops): sys.exit(1)
if c.get("displayRows")!=len(keep): sys.exit(1)
rows=c.get("rows") or []
if len(rows)!=len(keep): sys.exit(1)
sys.exit(0)
